package com.hms.availability;
import com.hms.doctors.*; import com.hms.tenancy.*; import java.time.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/doctors/{doctorId}/availability") public class PublicAvailabilityController {private final TenantRepository tenants;private final DoctorRepository doctors;private final AvailabilityController availability;public PublicAvailabilityController(TenantRepository t,DoctorRepository d,AvailabilityController a){tenants=t;doctors=d;availability=a;} @GetMapping public List<AvailableSlotDto> slots(@PathVariable String tenantSlug,@PathVariable UUID doctorId,@RequestParam LocalDate date){Tenant tenant=tenants.findBySlug(tenantSlug).filter(x->x.getStatus()!=TenantStatus.SUSPENDED&&x.getStatus()!=TenantStatus.CANCELLED&&x.getStatus()!=TenantStatus.EXPIRED).orElseThrow(()->new IllegalArgumentException("Hospital is not accepting appointments"));doctors.findById(doctorId).filter(d->d.getTenantId().equals(tenant.getId())&&d.isActive()&&d.isPublicVisible()).orElseThrow(()->new IllegalArgumentException("Doctor is not available for public booking"));return availability.availableSlots(tenantSlug,doctorId,date);} }
